import { LitElement, html, css } from 'https://cdn.skypack.dev/lit';

class DmoButton extends LitElement {
  static styles = css`
    button {
      padding: 10px 20px;
      font-size: 16px;
      background-color: #007bff;
      color: white;
      border: none;
      border-radius: 5px;
      cursor: pointer;
    }

    button:hover {
      background-color: #0056b3;
    }
  `;

  render() {
    return html`<button><slot></slot></button>`;
  }
}

customElements.define('dmo-button', DmoButton);
